{"cards": [{"node_code": "N_1fdf1ee217a90ad6", "definition": "研究隧道开挖前后山体（围岩）应力分布、变形规律及荷载传递机理的理论，涵盖初始地应力、开挖卸荷效应及长期稳定性分析。", "boundary": "本节点聚焦于“山体/围岩”作为荷载源或介质的力学行为。边界在于区分“山体压力”与“衬砌结构”（前者关注外部荷载来源，后者关注内部承载结构）。若内容涉及具体的现场压力计读数或监测方案，侧重数据获取归观测，侧重力学解释归本节点。", "includes": ["隧道围岩应力场与位移场理论分析", "山体压力（荷载）的计算模型与估算方法", "开挖扰动下围岩稳定性及荷载传递机理"], "excludes": ["隧道衬砌结构本身的力学计算", "列车通过引起的动力荷载分析"], "sibling_distinctions": [{"other_code": "N_ff4805ad6fee243d", "rule": "本节点侧重山体作为荷载源的压力分析与观测，兄弟节点侧重围岩本身的力学性质、分类及支护理论。"}, {"other_code": "N_4c03be8744da7220", "rule": "本节点关注外部山体对隧道的作用，兄弟节点关注隧道衬砌结构自身的受力与变形。"}], "cross_boundary_rule": "若内容涉及“围岩-衬砌共同作用”，侧重围岩侧归本节点或围岩理论，侧重衬砌侧归衬砌理论；若涉及具体监测数据，需区分是理论模型还是实测数据。"}, {"node_code": "N_ff4805ad6fee243d", "definition": "研究隧道周围岩体的力学性质、分类标准、变形破坏机理及支护原理的理论，涵盖围岩分级、强度理论及锚喷支护力学分析。", "boundary": "本节点聚焦于“围岩”这一介质本身的属性及其与支护结构的相互作用理论。边界在于区分“围岩理论”与“山体压力”（前者侧重材料属性与支护，后者侧重荷载计算）。若内容涉及具体的围岩分级表或支护参数设计，归本节点；若涉及现场岩芯试验数据，归试验。", "includes": ["围岩力学性质、分类分级理论", "围岩变形、破坏机理及稳定性分析", "锚杆、喷射混凝土等支护结构的力学原理"], "excludes": ["隧道衬砌结构（如混凝土拱）的独立力学计算", "山体初始地应力的具体测量方法"], "sibling_distinctions": [{"other_code": "N_1fdf1ee217a90ad6", "rule": "本节点侧重围岩材料属性与支护理论，兄弟节点侧重山体压力荷载的计算与观测。"}, {"other_code": "N_4c03be8744da7220", "rule": "本节点关注围岩与支护的相互作用，兄弟节点关注隧道衬砌结构本身的力学行为。"}], "cross_boundary_rule": "若内容涉及“新奥法”等基于围岩理论的施工方法，主挂载本节点；若涉及具体支护结构设计图纸，归勘测设计。"}, {"node_code": "N_a0a8b2a39f6b6692", "definition": "研究列车（或车辆）通过隧道时产生的气动效应、振动荷载及其对隧道结构动力响应影响的理论，涵盖风压、噪声及共振分析。", "boundary": "本节点聚焦于“动态荷载”及其对结构的影响。边界在于区分“列车通过影响”与“静态山体压力”（前者为时变荷载，后者为静态或准静态）。若内容涉及列车空气动力学基础，归本节点；若涉及隧道内通风设施设计，归附属设施。", "includes": ["列车通过隧道时的活塞风效应理论", "列车振动对隧道结构的动力响应分析", "隧道内气动噪声及共振机理研究"], "excludes": ["隧道静态结构受力分析", "列车车辆本身的空气动力学设计"], "sibling_distinctions": [{"other_code": "N_1fdf1ee217a90ad6", "rule": "本节点关注动态交通荷载，兄弟节点关注静态山体荷载。"}, {"other_code": "N_ff4805ad6fee243d", "rule": "本节点关注外部动态激励，兄弟节点关注围岩介质属性。"}], "cross_boundary_rule": "若内容涉及“列车-隧道-轨道”耦合振动，主挂载本节点；若仅涉及隧道结构静力计算，归衬砌理论或山体压力。"}]}
